{
    "level": "B1",
    "intro": "У цій темі ти навчишся розрізняти <strong>another, other, the other</strong>, а також <strong>others / the others</strong>.",
    "rules": [
        {
            "label": "ONE MORE",
            "color": "emerald",
            "text": "<strong>Another</strong> = ще один або інший один предмет.",
            "example": "Can I have another coffee?"
        },
        {
            "label": "DIFFERENT / MORE",
            "color": "blue",
            "text": "<strong>Other</strong> вживаємо з множиною або незлічуваними іменниками.",
            "example": "other people / other information"
        },
        {
            "label": "THE REMAINING ONE",
            "color": "amber",
            "text": "<strong>The other</strong> = той другий / той, що залишився.",
            "example": "One bag is mine, and the other bag is yours."
        }
    ]
}

{
    "title": "1. Основні відмінності",
    "intro": "Подивись, яка форма з яким типом іменника працює.",
    "items": [
        {
            "label": "один предмет",
            "title": "another + singular noun",
            "subtitle": "another day, another cup, another idea"
        },
        {
            "label": "інші / додаткові",
            "title": "other + plural / uncountable noun",
            "subtitle": "other books, other people, other information"
        },
        {
            "label": "конкретний другий",
            "title": "the other + singular noun",
            "subtitle": "the other hand, the other room"
        },
        {
            "label": "без іменника",
            "title": "others / the others",
            "subtitle": "Some are ready; the others are late."
        }
    ]
}

{
    "title": "2. Коли вживати кожну форму",
    "sections": [
        {
            "label": "Another = ще один",
            "color": "emerald",
            "description": "<strong>Another</strong> поєднується з одниною і часто означає «ще один» або «інший» із подібної групи.",
            "examples": [
                {
                    "en": "Can I have another sandwich?",
                    "ua": "Можна мені ще один сендвіч?"
                },
                {
                    "en": "Let us try another method.",
                    "ua": "Давай спробуємо інший метод."
                },
                {
                    "en": "She stayed for another hour.",
                    "ua": "Вона залишилася ще на одну годину."
                }
            ]
        },
        {
            "label": "Other = інші / додаткові",
            "color": "blue",
            "description": "<strong>Other</strong> стоїть перед множиною або незлічуваним іменником.",
            "examples": [
                {
                    "en": "Other students were already inside.",
                    "ua": "Інші студенти вже були всередині."
                },
                {
                    "en": "Do you have any other questions?",
                    "ua": "У вас є ще якісь інші питання?"
                },
                {
                    "en": "We need other information.",
                    "ua": "Нам потрібна інша інформація."
                }
            ]
        },
        {
            "label": "The other / the others = той, що залишився",
            "color": "amber",
            "description": "<strong>The other</strong> — конкретний другий або останній один; <strong>the others</strong> — решта з групи.",
            "examples": [
                {
                    "en": "I have two keys. One is old and the other is new.",
                    "ua": "У мене два ключі. Один старий, а другий новий."
                },
                {
                    "en": "Some students passed, but the others failed.",
                    "ua": "Деякі студенти склали, а решта — ні."
                },
                {
                    "en": "This side is clean. The other side is dirty.",
                    "ua": "Цей бік чистий. Інший бік брудний."
                }
            ],
            "note": "Без іменника використовуємо <strong>others / the others</strong>, а не <span class=\"line-through\">other ones</span> за замовчуванням."
        }
    ]
}

{
    "title": "3. Типові помилки",
    "items": [
        {
            "label": "Помилка 1",
            "color": "rose",
            "title": "Another з множиною.",
            "wrong": "another books",
            "right": "✅ <span class=\"font-mono\">other books</span> / <span class=\"font-mono\">another book</span>"
        },
        {
            "label": "Помилка 2",
            "color": "amber",
            "title": "Other без іменника, коли треба others.",
            "wrong": "Some students are here, and other are late.",
            "right": "✅ <span class=\"font-mono\">Some students are here, and others are late.</span>"
        },
        {
            "label": "Помилка 3",
            "color": "sky",
            "title": "Пропуск the в конкретному значенні.",
            "wrong": "One shoe is black, other shoe is brown.",
            "right": "✅ <span class=\"font-mono\">One shoe is black, the other shoe is brown.</span>"
        }
    ]
}

{
    "title": "4. Короткий конспект",
    "items": [
        "<strong>Another</strong> = ще один / інший один предмет.",
        "<strong>Other</strong> = інші або додаткові речі / люди; йде з множиною або незлічуваним іменником.",
        "<strong>The other</strong> = конкретний другий або той, що залишився.",
        "<strong>Others / the others</strong> використовуємо без іменника.",
        "Питай себе: це ще один, інші взагалі чи конкретний той, що залишився?"
    ]
}

{
    "title": "Сторінки цього розділу",
    "items": [
        {
            "label": "Plural Nouns",
            "url": "/theory/imennyky-artykli-ta-kilkist/plural-nouns-s-es-ies",
            "current": false
        },
        {
            "label": "Countable / Uncountable Nouns",
            "url": "/theory/imennyky-artykli-ta-kilkist/countable-vs-uncountable-nouns",
            "current": false
        },
        {
            "label": "Articles — A / An / The",
            "url": "/theory/imennyky-artykli-ta-kilkist/articles-a-an-the",
            "current": false
        },
        {
            "label": "Quantifiers — much, many, few, little",
            "url": "/theory/imennyky-artykli-ta-kilkist/quantifiers-much-many-a-lot-few-little",
            "current": false
        },
        {
            "label": "Collective Nouns",
            "url": "/theory/imennyky-artykli-ta-kilkist/collective-nouns",
            "current": false
        },
        {
            "label": "Another / Other / The Other",
            "url": "/theory/imennyky-artykli-ta-kilkist/another-other-the-other",
            "current": true
        },
        {
            "label": "Partitives — a piece of, a cup of...",
            "url": "/theory/imennyky-artykli-ta-kilkist/partitives-with-uncountable-nouns-a-piece-of-a-cup-of",
            "current": false
        },
        {
            "label": "No / None / Neither / Either",
            "url": "/theory/imennyky-artykli-ta-kilkist/no-none-neither-either",
            "current": false
        }
    ]
}

{
    "level": "A1–B1",
    "intro": "У цій темі ти вивчиш <strong>всі основні типи займенників<\/strong> англійської мови та правила їх вживання.",
    "rules": [
        {
            "label": "Personal",
            "color": "emerald",
            "text": "<strong>Особові займенники<\/strong> — хто діє:",
            "example": "I work. She reads. They play."
        },
        {
            "label": "Possessive",
            "color": "blue",
            "text": "<strong>Присвійні форми<\/strong> — чиє це:",
            "example": "my book, mine, his, hers"
        },
        {
            "label": "Reflexive",
            "color": "amber",
            "text": "<strong>Зворотні займенники<\/strong> — дія на себе:",
            "example": "I did it myself. She taught herself."
        }
    ]
}

{
    "title": "1. Типи займенників",
    "intro": "В англійській мові є кілька основних типів займенників:",
    "items": [
        {
            "label": "Personal",
            "title": "Особові",
            "subtitle": "I, you, he, she, it, we, they — хто діє або отримує дію"
        },
        {
            "label": "Possessive",
            "title": "Присвійні",
            "subtitle": "my\/mine, your\/yours, his, her\/hers — чиє це"
        },
        {
            "label": "Reflexive",
            "title": "Зворотні",
            "subtitle": "myself, yourself, himself, herself — дія на себе"
        },
        {
            "label": "Demonstrative",
            "title": "Вказівні",
            "subtitle": "this, that, these, those — вказують на предмети"
        },
        {
            "label": "Indefinite",
            "title": "Неозначені",
            "subtitle": "someone, anybody, nothing — невизначені особи\/речі"
        },
        {
            "label": "Relative",
            "title": "Відносні",
            "subtitle": "who, which, that — з'єднують частини речення"
        }
    ]
}

{
    "title": "2. Особові займенники (Personal Pronouns)",
    "sections": [
        {
            "label": "Subject Pronouns — Підметові",
            "color": "emerald",
            "description": "Використовуються як <strong>підмет<\/strong> речення (хто виконує дію).",
            "examples": [
                {
                    "en": "I work every day.",
                    "ua": "Я працюю щодня."
                },
                {
                    "en": "You are smart.",
                    "ua": "Ти розумний."
                },
                {
                    "en": "He reads books.",
                    "ua": "Він читає книги."
                },
                {
                    "en": "She likes music.",
                    "ua": "Вона любить музику."
                },
                {
                    "en": "It is a cat.",
                    "ua": "Це кіт."
                },
                {
                    "en": "We are friends.",
                    "ua": "Ми друзі."
                },
                {
                    "en": "They play football.",
                    "ua": "Вони грають у футбол."
                }
            ]
        },
        {
            "label": "Object Pronouns — Об'єктні",
            "color": "sky",
            "description": "Використовуються як <strong>додаток<\/strong> (хто\/що отримує дію).",
            "examples": [
                {
                    "en": "Call me later.",
                    "ua": "Подзвони мені пізніше."
                },
                {
                    "en": "I see you.",
                    "ua": "Я бачу тебе."
                },
                {
                    "en": "She loves him.",
                    "ua": "Вона любить його."
                },
                {
                    "en": "I know her.",
                    "ua": "Я знаю її."
                },
                {
                    "en": "Give it to me.",
                    "ua": "Дай це мені."
                },
                {
                    "en": "They invited us.",
                    "ua": "Вони запросили нас."
                },
                {
                    "en": "I like them.",
                    "ua": "Мені вони подобаються."
                }
            ]
        },
        {
            "label": "Таблиця особових займенників",
            "color": "purple",
            "description": "Повна таблиця підметових та об'єктних займенників:",
            "examples": [
                {
                    "en": "I → me",
                    "ua": "я → мене"
                },
                {
                    "en": "you → you",
                    "ua": "ти\/ви → тебе\/вас"
                },
                {
                    "en": "he → him",
                    "ua": "він → його"
                },
                {
                    "en": "she → her",
                    "ua": "вона → її"
                },
                {
                    "en": "it → it",
                    "ua": "воно → його\/її"
                },
                {
                    "en": "we → us",
                    "ua": "ми → нас"
                },
                {
                    "en": "they → them",
                    "ua": "вони → їх"
                }
            ],
            "note": "📌 Subject = підмет (хто діє), Object = додаток (кого\/що)."
        }
    ]
}

{
    "title": "3. Присвійні форми (Possessive Forms)",
    "sections": [
        {
            "label": "Possessive Adjectives — Присвійні прикметники",
            "color": "blue",
            "description": "Стоять <strong>перед іменником<\/strong> і показують приналежність.",
            "examples": [
                {
                    "en": "This is my book.",
                    "ua": "Це моя книга."
                },
                {
                    "en": "Your car is new.",
                    "ua": "Твоя машина нова."
                },
                {
                    "en": "His name is John.",
                    "ua": "Його ім'я Джон."
                },
                {
                    "en": "Her sister is a doctor.",
                    "ua": "Її сестра — лікар."
                },
                {
                    "en": "Its color is blue.",
                    "ua": "Його колір синій."
                },
                {
                    "en": "Our house is big.",
                    "ua": "Наш будинок великий."
                },
                {
                    "en": "Their dog is cute.",
                    "ua": "Їхня собака мила."
                }
            ],
            "note": "Завжди перед іменником!"
        },
        {
            "label": "Possessive Pronouns — Присвійні займенники",
            "color": "sky",
            "description": "<strong>Заміняють<\/strong> іменник (стоять замість нього).",
            "examples": [
                {
                    "en": "This book is mine.",
                    "ua": "Ця книга моя."
                },
                {
                    "en": "The car is yours.",
                    "ua": "Машина твоя."
                },
                {
                    "en": "That pen is his.",
                    "ua": "Та ручка його."
                },
                {
                    "en": "The bag is hers.",
                    "ua": "Сумка її."
                },
                {
                    "en": "The house is ours.",
                    "ua": "Будинок наш."
                },
                {
                    "en": "Those keys are theirs.",
                    "ua": "Ті ключі їхні."
                }
            ],
            "note": "Стоять самостійно, без іменника!"
        },
        {
            "label": "Важливо!",
            "color": "amber",
            "description": "Не плутай <strong>its<\/strong> (присвійне) та <strong>it's<\/strong> (скорочення).",
            "examples": [
                {
                    "en": "Its color is red. (присвійне)",
                    "ua": "Його колір червоний."
                },
                {
                    "en": "It's a cat. (it is)",
                    "ua": "Це кіт."
                }
            ],
            "note": "📌 Its = присвійне, It's = скорочення від It is."
        }
    ]
}

{
    "title": "4. Зворотні займенники (Reflexive Pronouns)",
    "sections": [
        {
            "label": "Форми зворотних займенників",
            "color": "purple",
            "description": "Закінчуються на <strong>-self<\/strong> (однина) або <strong>-selves<\/strong> (множина).",
            "examples": [
                {
                    "en": "I → myself",
                    "ua": "я → себе (сам\/сама)"
                },
                {
                    "en": "you → yourself \/ yourselves",
                    "ua": "ти\/ви → себе"
                },
                {
                    "en": "he → himself",
                    "ua": "він → себе (сам)"
                },
                {
                    "en": "she → herself",
                    "ua": "вона → себе (сама)"
                },
                {
                    "en": "it → itself",
                    "ua": "воно → себе (саме)"
                },
                {
                    "en": "we → ourselves",
                    "ua": "ми → себе (самі)"
                },
                {
                    "en": "they → themselves",
                    "ua": "вони → себе (самі)"
                }
            ]
        },
        {
            "label": "Коли вживати",
            "color": "emerald",
            "description": "Коли <strong>підмет і об'єкт<\/strong> — одна й та сама особа.",
            "examples": [
                {
                    "en": "I taught myself English.",
                    "ua": "Я навчив себе (сам навчився) англійської."
                },
                {
                    "en": "She cut herself.",
                    "ua": "Вона порізалася (порізала себе)."
                },
                {
                    "en": "We enjoyed ourselves.",
                    "ua": "Ми добре провели час (розважили себе)."
                },
                {
                    "en": "They did it themselves.",
                    "ua": "Вони зробили це самі."
                }
            ]
        },
        {
            "label": "Emphatic use — Підсилення",
            "color": "amber",
            "description": "Для <strong>підсилення<\/strong>: акцент на тому, хто саме виконав дію.",
            "examples": [
                {
                    "en": "I did it myself.",
                    "ua": "Я зробив це сам (сам, без допомоги)."
                },
                {
                    "en": "The boss himself came.",
                    "ua": "Сам бос прийшов."
                },
                {
                    "en": "She fixed the car herself.",
                    "ua": "Вона сама полагодила машину."
                }
            ],
            "note": "📌 By myself\/yourself = самостійно, без допомоги."
        }
    ]
}

{
    "title": "5. Вказівні займенники (Demonstrative Pronouns)",
    "sections": [
        {
            "label": "This \/ That — Однина",
            "color": "blue",
            "description": "<strong>This<\/strong> — близько, <strong>That<\/strong> — далеко.",
            "examples": [
                {
                    "en": "This is my phone.",
                    "ua": "Це мій телефон. (близько)"
                },
                {
                    "en": "That is your car.",
                    "ua": "Те — твоя машина. (далеко)"
                },
                {
                    "en": "I like this.",
                    "ua": "Мені це подобається."
                },
                {
                    "en": "What is that?",
                    "ua": "Що то таке?"
                }
            ]
        },
        {
            "label": "These \/ Those — Множина",
            "color": "sky",
            "description": "<strong>These<\/strong> — близько, <strong>Those<\/strong> — далеко.",
            "examples": [
                {
                    "en": "These are my books.",
                    "ua": "Це мої книги. (близько)"
                },
                {
                    "en": "Those are your keys.",
                    "ua": "Ті — твої ключі. (далеко)"
                },
                {
                    "en": "I want these.",
                    "ua": "Я хочу ці."
                },
                {
                    "en": "Those are expensive.",
                    "ua": "Ті дорогі."
                }
            ],
            "note": "📌 This\/That = однина, These\/Those = множина."
        }
    ]
}

{
    "title": "6. Інші типи займенників (огляд)",
    "sections": [
        {
            "label": "Indefinite Pronouns — Неозначені",
            "color": "purple",
            "description": "Вказують на невизначених осіб або речі.",
            "examples": [
                {
                    "en": "Someone is calling.",
                    "ua": "Хтось телефонує."
                },
                {
                    "en": "Anybody can do it.",
                    "ua": "Будь-хто може це зробити."
                },
                {
                    "en": "Nothing is impossible.",
                    "ua": "Ніщо не є неможливим."
                },
                {
                    "en": "Everybody knows that.",
                    "ua": "Всі це знають."
                }
            ]
        },
        {
            "label": "Relative Pronouns — Відносні",
            "color": "emerald",
            "description": "З'єднують частини складного речення.",
            "examples": [
                {
                    "en": "The man who called is my boss.",
                    "ua": "Чоловік, який телефонував — мій бос."
                },
                {
                    "en": "The book that I read was great.",
                    "ua": "Книга, яку я прочитав, була чудова."
                },
                {
                    "en": "The car which is red is mine.",
                    "ua": "Машина, яка червона — моя."
                }
            ]
        },
        {
            "label": "Reciprocal Pronouns — Взаємні",
            "color": "amber",
            "description": "Вказують на взаємну дію.",
            "examples": [
                {
                    "en": "They love each other.",
                    "ua": "Вони люблять один одного."
                },
                {
                    "en": "We help one another.",
                    "ua": "Ми допомагаємо один одному."
                }
            ],
            "note": "📌 Each other = для двох, One another = для багатьох."
        }
    ]
}

{
    "title": "7. Порівняльна таблиця основних займенників",
    "intro": "Основні форми займенників:",
    "rows": [
        {
            "en": "Subject",
            "ua": "Підмет",
            "note": "I, you, he, she, it, we, they"
        },
        {
            "en": "Object",
            "ua": "Додаток",
            "note": "me, you, him, her, it, us, them"
        },
        {
            "en": "Possessive Adj.",
            "ua": "Присвійний прикм.",
            "note": "my, your, his, her, its, our, their"
        },
        {
            "en": "Possessive Pron.",
            "ua": "Присвійний займ.",
            "note": "mine, yours, his, hers, ours, theirs"
        },
        {
            "en": "Reflexive",
            "ua": "Зворотний",
            "note": "myself, yourself, himself, herself, itself, ourselves, yourselves, themselves"
        }
    ],
    "warning": "📌 Subject = підмет, Object = додаток, Possessive = присвійний, Reflexive = зворотний."
}

{
    "title": "8. Типові помилки україномовних",
    "items": [
        {
            "label": "Помилка 1",
            "color": "rose",
